export interface WorkItem {
  id: number;
  title: string;
  dueLabel: string;
}

function copyItem(item: WorkItem): WorkItem {
  return { id: item.id, title: item.title, dueLabel: item.dueLabel };
}

export class WorkQueue {
  private items: WorkItem[] = [];
  private nextId = 1;

  add(title: string, dueLabel: string): WorkItem {
    const cleanTitle = title.trim();
    const cleanDueLabel = dueLabel.trim();
    if (cleanTitle.length === 0 || dueLabel.length === 0) {
      throw new TypeError("title and dueLabel must not be blank");
    }
    if (!Number.isSafeInteger(this.nextId)) {
      throw new RangeError("no safe IDs remain");
    }
    const item: WorkItem = {
      id: this.nextId,
      title: cleanTitle,
      dueLabel: cleanDueLabel,
    };
    this.nextId += 1;
    this.items = [...this.items, item];
    return copyItem(item);
  }

  complete(id: number): boolean {
    if (!Number.isSafeInteger(id)) {
      throw new TypeError("id must be a safe integer");
    }
    const index = this.items.findIndex((item) => item.id === id);
    if (index < 0) return false;
    this.items = [...this.items.slice(0, index), ...this.items.slice(index + 1)];
    return true;
  }

  list(): WorkItem[] {
    return this.items.map(copyItem);
  }
}

