import { WorkQueue } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsTypeError(action: () => void, message: string): void {
  try { action(); } catch (error) { if (error instanceof TypeError) return; throw new Error(`${message}: wrong error`); }
  throw new Error(`${message}: did not throw`);
}

const queue = new WorkQueue();
equal(queue.list().length, 0, 'new queue is empty');

const first = queue.add('  Write tests  ', '  Today  ');
equal(first.id, 1, 'first id is one');
equal(first.title, 'Write tests', 'title is trimmed');
equal(first.dueLabel, 'Today', 'due label is trimmed');
first.title = 'Changed';
equal(queue.list()[0].title, 'Write tests', 'add returns a copy');

const second = queue.add('Review', 'Tomorrow');
equal(second.id, 2, 'ids increase');
const listA = queue.list();
const listB = queue.list();
assert(listA !== listB, 'list returns a fresh array');
assert(listA[0] !== listB[0], 'list returns fresh objects');
listA.reverse();
listB[0].title = 'Mutated';
equal(queue.list().map((item) => item.id).join(','), '1,2', 'returned values do not alias state');

equal(queue.complete(1), true, 'complete removes a matching item');
equal(queue.list().map((item) => item.id).join(','), '2', 'remaining order is retained');
equal(queue.complete(1), false, 'complete reports an absent item');

const beforeFailure = queue.list();
throwsTypeError(() => queue.add('   ', 'Later'), 'blank title');
throwsTypeError(() => queue.add('Task', '\t '), 'blank due label');
throwsTypeError(() => queue.complete(2.5), 'fractional id');
throwsTypeError(() => queue.complete(Number.MAX_SAFE_INTEGER + 1), 'unsafe id');
equal(queue.list().length, beforeFailure.length, 'failed operations preserve queue');
equal(queue.list()[0].id, 2, 'failed operations preserve contents');

